    if tag == "isnull":
        return ("isnull", _rewrite_where(node[1], wide_name), node[2])
    if tag == "cmp":
        return (
            "cmp",
            node[1],
            _rewrite_where(node[2], wide_name),
            _rewrite_where(node[3], wide_name),
        )
    raise QuerySyntaxError(f"unsupported expression: {tag}")  # pragma: no cover


